<script setup>
import {ref, computed, onMounted, onBeforeUnmount} from 'vue'
import MapView from './MapView.vue'
const products=ref([]), reviews=ref([]), messages=ref([]), conversations=ref([])
const active=ref('home'),selected=ref(null),conversation=ref(null),filter=ref('Tutti'),search=ref('')
const user=ref(null),csrf=ref(''),error=ref(''),notice=ref(''),busy=ref(false),authMode=ref('login')
const credentials=ref({name:'',email:'',password:'',kind:'privato'})
const recovery=ref({email:'',password:'',token:''}), reportForm=ref({kind:'annuncio',target_id:null,reason:''})
const form=ref({name:'',category:'Verdura',exchange:'Vendo',price:'',description:''})
const message=ref(''), review=ref({rating:5,body:''})
let events=null
const categories=['Tutti','Verdura','Frutta','Uova','Miele','Gratis','Baratto']
const emoji={Verdura:'🥬',Frutta:'🍎',Uova:'🥚',Miele:'🍯',Altro:'🌿'}
const visible=computed(()=>products.value.filter(p=>(filter.value==='Tutti'||p.category===filter.value||(filter.value==='Gratis'&&p.exchange==='Regalo')||(filter.value==='Baratto'&&p.exchange==='Baratto'))&&`${p.name} ${p.seller}`.toLowerCase().includes(search.value.toLowerCase())))
const date=s=>s?new Date(s).toLocaleString('it-IT'):'adesso'
async function api(path,options={}){
 const response=await fetch('/api'+path,{credentials:'same-origin',headers:{'Content-Type':'application/json',...(csrf.value?{'X-CSRF-Token':csrf.value}:{})},...options})
 let data;try{data=await response.json()}catch{throw new Error('Risposta del server non valida')}
 if(!response.ok)throw new Error(data.error||'Errore di comunicazione')
 return data
}
async function load(){try{products.value=await api('/products')}catch(e){error.value='Backend non raggiungibile: controlla che Elixir sia avviato sulla porta 4000.'}}
async function restore(){try{const data=await api('/me');user.value=data.user;csrf.value=data.csrf}catch{user.value=null;csrf.value=''}}
async function authenticate(){busy.value=true;error.value='';try{const endpoint=authMode.value==='login'?'/login':'/register';const result=await api(endpoint,{method:'POST',body:JSON.stringify(credentials.value)});if(authMode.value==='register'){active.value='auth';authMode.value='login';notice.value='Registrazione ricevuta. Controlla la tua email prima di accedere.'}else{user.value=result.user;csrf.value=result.csrf;active.value='profile';notice.value='Accesso effettuato!'}credentials.value.password=''}catch(e){error.value=e.message}finally{busy.value=false}}
async function logout(){try{await api('/logout',{method:'POST'})}catch(e){error.value=e.message}closeEvents();user.value=null;csrf.value='';active.value='home';notice.value='Disconnessione effettuata'}
function requireLogin(target){if(!user.value){notice.value='Accedi o registrati per continuare';active.value='auth';return false}active.value=target;return true}
function openProduct(p){closeEvents();selected.value=p;active.value='detail';notice.value='';error.value=''}
async function submitProduct(){if(!user.value)return requireLogin('publish');busy.value=true;error.value='';try{const p=await api('/products',{method:'POST',body:JSON.stringify({...form.value,latitude:43.9304,longitude:11.0402})});await load();selected.value=p;active.value='detail';notice.value='Annuncio pubblicato!';form.value={name:'',category:'Verdura',exchange:'Vendo',price:'',description:''}}catch(e){error.value=e.message}finally{busy.value=false}}
function closeEvents(){if(events){events.close();events=null}}
async function openConversation(c){try{closeEvents();conversation.value=c;messages.value=await api(`/conversations/${c.id}/messages`);active.value='chat';events=new EventSource(`/api/conversations/${c.id}/events`);events.addEventListener('message',e=>{const m=JSON.parse(e.data);if(!messages.value.some(x=>x.id===m.id))messages.value.push(m)});events.onerror=()=>{notice.value='Connessione chat interrotta: riconnessione automatica in corso'}}catch(e){error.value=e.message}}
async function contact(){if(!user.value)return requireLogin('auth');try{const c=await api(`/products/${selected.value.id}/conversations`,{method:'POST'});await openConversation(c)}catch(e){error.value=e.message}}
async function inbox(){if(!requireLogin('inbox'))return;try{conversations.value=await api('/conversations')}catch(e){error.value=e.message}}
async function sendMessage(){if(!message.value.trim()||!conversation.value)return;busy.value=true;try{const result=await api(`/conversations/${conversation.value.id}/messages`,{method:'POST',body:JSON.stringify({body:message.value})});if(!messages.value.some(m=>m.id===result.id))messages.value.push(result);message.value='';notice.value=''}catch(e){error.value=e.message}finally{busy.value=false}}
async function showReviews(){try{reviews.value=await api(`/products/${selected.value.id}/reviews`);active.value='reviews'}catch(e){error.value=e.message}}
async function sendReview(){if(!user.value)return requireLogin('auth');busy.value=true;try{await api(`/products/${selected.value.id}/reviews`,{method:'POST',body:JSON.stringify(review.value)});review.value={rating:5,body:''};notice.value='Recensione pubblicata';await showReviews()}catch(e){error.value=e.message}finally{busy.value=false}}
async function recover(){busy.value=true;error.value='';try{const result=await api('/forgot-password',{method:'POST',body:JSON.stringify({email:recovery.value.email})});notice.value=result.message;active.value='auth'}catch(e){error.value=e.message}finally{busy.value=false}}
async function resetPassword(){busy.value=true;error.value='';try{await api('/reset-password',{method:'POST',body:JSON.stringify(recovery.value)});recovery.value.password='';notice.value='Password aggiornata: ora puoi accedere.';active.value='auth'}catch(e){error.value=e.message}finally{busy.value=false}}
async function verifyEmail(token){try{await api('/verify-email',{method:'POST',body:JSON.stringify({token})});notice.value='Email verificata! Adesso puoi accedere.';active.value='auth'}catch(e){error.value=e.message;active.value='auth'}}
function startReport(kind,id){if(!user.value)return requireLogin('auth');reportForm.value={kind,target_id:id,reason:''};active.value='report'}
async function sendReport(){busy.value=true;error.value='';try{const result=await api('/reports',{method:'POST',body:JSON.stringify(reportForm.value)});notice.value=result.message;active.value='detail'}catch(e){error.value=e.message}finally{busy.value=false}}
function home(){closeEvents();active.value='home';notice.value='';error.value=''}
const wa=()=>window.open('https://api.whatsapp.com/send?text='+encodeURIComponent(`Ciao, sono interessato a ${selected.value?.name}. Possiamo concordare il ritiro?`),'_blank','noopener,noreferrer')
onMounted(async()=>{const query=new URLSearchParams(location.search);if(query.has('verify')){await verifyEmail(query.get('verify'));history.replaceState({},'',location.pathname)}else if(query.has('reset')){recovery.value.token=query.get('reset');active.value='reset';history.replaceState({},'',location.pathname)}await Promise.all([load(),restore()])})
onBeforeUnmount(closeEvents)
</script>
<template>
<div class="shell"><div class="phone">
<header class="header"><button v-if="active!=='home'" class="back" @click="home">‹</button><div><div class="brand">🌱 OrtoVicino</div><small>Dal territorio, per il territorio</small></div><button class="userbutton" @click="active=user?'profile':'auth'">{{user?'👤':'Accedi'}}</button></header>
<main class="main">
 <p v-if="error" class="alert" role="alert">{{error}} <button @click="error=''">✕</button></p>
 <p v-if="notice" class="success">{{notice}}</p>
 <template v-if="active==='home'">
  <section class="greeting"><h1>Il buono è vicino a te 🌿</h1><p>Scopri raccolti freschi, regali e baratti nella tua zona.</p></section>
  <div class="search">⌕ <input v-model="search" placeholder="Cerca prodotti o persone" aria-label="Cerca prodotti"></div>
  <div class="chips"><button v-for="c in categories" :key="c" :class="['chip',{chosen:filter===c}]" @click="filter=c">{{c}}</button></div>
  <div class="section-title"><h2>Esplora la zona</h2><small>📍 Montemurlo (PO)</small></div><MapView :products="visible" @select="openProduct"/>
  <div class="section-title"><h2>Prodotti disponibili</h2><small>{{visible.length}} annunci</small></div>
  <button v-for="p in visible" :key="p.id" class="item" @click="openProduct(p)"><span class="thumb">{{emoji[p.category]||'🌿'}}</span><span class="item-body"><b>{{p.name}}</b><small>{{p.seller}} · {{p.seller_type==='privato'?'Privato':'Produttore'}}</small><span class="available">{{p.exchange==='Regalo'?'🎁 Gratis':p.exchange==='Baratto'?'⇄ Baratto':p.price||'Da concordare'}}</span></span><span class="arrow">›</span></button>
 </template>
 <template v-else-if="active==='auth'"><div class="content"><h1>{{authMode==='login'?'Bentornato! 🌼':'Entra nella community 🌱'}}</h1><p>{{authMode==='login'?'Accedi per chattare e lasciare recensioni.':'Crea un account gratuito per pubblicare e condividere.'}}</p>
  <div class="actions"><button class="secondary" @click="authMode='login'">Accedi</button><button class="secondary" @click="authMode='register'">Registrati</button></div>
  <form class="form" @submit.prevent="authenticate"><label v-if="authMode==='register'">Nome pubblico<input v-model="credentials.name" minlength="2" maxlength="70" required autocomplete="name"></label><label>Email<input v-model="credentials.email" required type="email" autocomplete="email"></label><label>Password<input v-model="credentials.password" type="password" required :minlength="authMode==='register'?12:1" maxlength="128" :autocomplete="authMode==='login'?'current-password':'new-password'"></label><label v-if="authMode==='register'">Profilo<select v-model="credentials.kind"><option value="privato">Privato</option><option value="professionista">Produttore agricolo</option></select></label><div class="privacy">🔐 Password cifrate con bcrypt. La sessione usa cookie HttpOnly. Usa almeno 12 caratteri.</div><button class="primary full" :disabled="busy">{{busy?'Attendi...':authMode==='login'?'Accedi':'Crea account'}}</button></form><button v-if="authMode==='login'" class="secondary full" @click="active='forgot'">Hai dimenticato la password?</button>
 </div></template>
 <template v-else-if="active==='forgot'"><div class="content"><h1>Recupera la password</h1><p>Ti invieremo un collegamento valido per 30 minuti.</p><form class="form" @submit.prevent="recover"><label>Indirizzo email<input required type="email" v-model="recovery.email" autocomplete="email"></label><button class="primary full" :disabled="busy">Invia collegamento</button></form></div></template>
 <template v-else-if="active==='reset'"><div class="content"><h1>Scegli una nuova password</h1><form class="form" @submit.prevent="resetPassword"><label>Nuova password<input required type="password" minlength="12" maxlength="128" v-model="recovery.password" autocomplete="new-password"></label><button class="primary full" :disabled="busy">Aggiorna password</button></form></div></template>
 <template v-else-if="active==='report'"><div class="content"><h1>Segnala un contenuto</h1><p>Descrivi il problema: la segnalazione verrà esaminata dagli amministratori.</p><form class="form" @submit.prevent="sendReport"><label>Motivo<textarea required minlength="10" maxlength="500" v-model="reportForm.reason" rows="4" placeholder="Spiega cosa non va, senza condividere dati sensibili"></textarea></label><button class="primary full" :disabled="busy">Invia segnalazione</button></form></div></template>
 <template v-else-if="active==='detail'&&selected"><div class="hero">{{emoji[selected.category]||'🌿'}}</div><div class="content"><h1>{{selected.name}}</h1><div class="price">{{selected.exchange==='Regalo'?'Gratis':selected.exchange==='Baratto'?'Baratto':selected.price||'Da concordare'}}</div><div class="tags"><span>✓ Disponibile</span><span>{{selected.category}}</span><span>{{selected.seller_type==='privato'?'🏡 Privato':'🚜 Professionista'}}</span></div><p>{{selected.description||'Prodotto locale. Ritiro su accordo.'}}</p><h2>Chi lo propone</h2><div class="seller">{{selected.seller}}<small>⭐ Recensioni della community</small></div><div class="privacy">{{selected.seller_type==='privato'?'🔒 Il server mostra solo un’area approssimativa, non il domicilio.':'📍 Concorda direttamente il punto di ritiro.'}}</div><div class="actions"><button class="secondary" @click="showReviews">⭐ Recensioni</button><button class="primary" :disabled="!selected.owner_id||user?.id===selected.owner_id" @click="contact">💬 Chat privata</button></div><button class="secondary full" @click="wa">Scrivi su WhatsApp ↗</button><p v-if="!selected.owner_id" class="tiny">Annuncio dimostrativo: per provare la chat, pubblicane uno da un account reale.</p><button v-if="user" class="secondary full" @click="startReport('annuncio',selected.id)">⚑ Segnala annuncio</button><p class="tiny">Nessuna commissione o pagamento nell’app.</p></div></template>
 <template v-else-if="active==='publish'"><div class="content"><h1>Condividi il raccolto 🌱</h1><p>Pubblica gratuitamente con il tuo profilo.</p><div v-if="!user" class="privacy">Accedi prima di pubblicare.</div><form v-else class="form" @submit.prevent="submitProduct"><label>Prodotto<input required minlength="2" maxlength="100" v-model="form.name" placeholder="Es. Zucchine dell’orto"></label><label>Categoria<select v-model="form.category"><option>Verdura</option><option>Frutta</option><option>Uova</option><option>Miele</option><option>Altro</option></select></label><label>Modalità<select v-model="form.exchange"><option>Vendo</option><option>Regalo</option><option>Baratto</option></select></label><label>Prezzo o quantità<input v-model="form.price" maxlength="100" placeholder="Es. 2 € / kg"></label><label>Descrizione<textarea v-model="form.description" maxlength="1000" rows="3"></textarea></label><div class="privacy">🔒 I privati vengono pubblicati con coordinate arrotondate dal server, mai con GPS preciso.</div><button class="primary full" :disabled="busy">{{busy?'Salvataggio...':'Pubblica annuncio'}}</button></form><button v-if="!user" class="primary full" @click="active='auth'">Vai al login</button></div></template>
 <template v-else-if="active==='inbox'"><div class="content"><h1>💬 Le tue conversazioni</h1><p>Visibili soltanto a te e alle persone coinvolte.</p><button v-for="c in conversations" :key="c.id" class="item" style="width:100%;margin:8px 0" @click="openConversation(c)"><span class="thumb">💬</span><span class="item-body"><b>{{c.product_name}}</b><small>{{c.seller}}</small></span><span class="arrow">›</span></button><p v-if="!conversations.length" class="empty">Non hai ancora conversazioni.</p></div></template>
 <template v-else-if="active==='chat'&&conversation"><div class="content"><h1>💬 Chat privata</h1><p>Annuncio: <b>{{conversation.product_name}}</b></p><div class="privacy">🔒 Solo venditore e acquirente possono leggere questa conversazione. I nuovi messaggi arrivano in tempo reale.</div><div class="message-list"><div v-for="m in messages" :key="m.id" :class="['message',{'mine':m.sender_id===user?.id}]"><b>{{m.sender_id===user?.id?'Tu':'Altra persona'}}</b><p>{{m.body}}</p><small>{{date(m.inserted_at)}}</small></div><p v-if="!messages.length" class="empty">Scrivi il primo messaggio.</p></div><form class="form" @submit.prevent="sendMessage"><label>Messaggio<textarea v-model="message" required maxlength="1000" rows="2" placeholder="Scrivi un messaggio..."></textarea></label><button class="primary full" :disabled="busy">Invia messaggio ➤</button></form></div></template>
 <template v-else-if="active==='reviews'&&selected"><div class="content"><h1>⭐ Recensioni</h1><p>Per {{selected.seller}}</p><div v-for="r in reviews" :key="r.id" class="review"><b>{{r.author}}</b><span>{{'★'.repeat(r.rating)}}{{'☆'.repeat(5-r.rating)}}</span><p>{{r.body}}</p><small>{{date(r.inserted_at)}}</small><button v-if="user" class="secondary" @click="startReport('recensione',r.id)">Segnala</button></div><p v-if="!reviews.length" class="empty">Ancora nessuna recensione.</p><h2>Lascia un feedback</h2><div v-if="!user" class="privacy">Per lasciare recensioni devi accedere.</div><form v-else class="form" @submit.prevent="sendReview"><label>Stelle<select v-model.number="review.rating"><option v-for="n in [5,4,3,2,1]" :key="n" :value="n">{{n}} stelle</option></select></label><label>Esperienza<textarea required minlength="2" maxlength="500" v-model="review.body" rows="3"></textarea></label><button class="primary full" :disabled="busy">Pubblica recensione</button></form><button v-if="!user" class="primary full" @click="active='auth'">Accedi</button></div></template>
 <template v-else-if="active==='profile'"><div class="content"><h1>Il tuo profilo 🌼</h1><div v-if="user"><div class="seller">{{user.name}}<small>{{user.kind==='privato'?'🏡 Privato':'🚜 Produttore'}}</small></div><div class="privacy">🔐 Accesso autenticato. Puoi pubblicare, chattare e recensire. Le password non vengono salvate in chiaro.</div><button class="primary full" @click="active='publish'">Pubblica un annuncio</button><button class="secondary full" @click="inbox">Apri messaggi</button><button class="secondary full" @click="logout">Esci dall’account</button></div><button v-else class="primary full" @click="active='auth'">Accedi o registrati</button></div></template>
</main>
<nav class="bottom"><button :class="{on:active==='home'}" @click="home">⌂<small>Home</small></button><button :class="{on:active==='publish'}" @click="requireLogin('publish')"><span class="plus">＋</span><small>Pubblica</small></button><button :class="{on:active==='chat'||active==='inbox'}" @click="inbox">♧<small>Messaggi</small></button><button :class="{on:active==='profile'||active==='auth'}" @click="active=user?'profile':'auth'">♙<small>Profilo</small></button></nav>
</div></div>
</template>
